let _markdown = "\n\n> <FeedbackBlock id=\"d9c0de87ebbbf4d3\" body=\"This is a community maintained integration.\">\n>   This is a community maintained integration.\n> </FeedbackBlock>\n\nIntroduction [#introduction]\n\n<FeedbackBlock id=\"53ebd6ed09027969\" body=\"The Trieve Integration automatically configures Trieve Search for site search.\">\n  The Trieve Integration automatically configures Trieve Search for site search.\n</FeedbackBlock>\n\n<FeedbackBlock\n  id=\"b5b85e3c7066ae79\"\n  body=\"By default, it creates a chunk for each paragraph in your document, it is\nofficially recommended by Trieve.\"\n>\n  By default, it creates a chunk for **each paragraph** in your document, it is\n  officially recommended by Trieve.\n</FeedbackBlock>\n\nSetup [#setup]\n\nInstall Dependencies [#install-dependencies]\n\n<CodeBlockTabs defaultValue=\"npm\" groupId=\"package-manager\" persist>\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"npm\">\n      npm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"pnpm\">\n      pnpm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"yarn\">\n      yarn\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"bun\">\n      bun\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"npm\">\n    ```bash\n    npm install trieve-ts-sdk trieve-fumadocs-adapter\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"pnpm\">\n    ```bash\n    pnpm add trieve-ts-sdk trieve-fumadocs-adapter\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"yarn\">\n    ```bash\n    yarn add trieve-ts-sdk trieve-fumadocs-adapter\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"bun\">\n    ```bash\n    bun add trieve-ts-sdk trieve-fumadocs-adapter\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\nSign up on Trieve [#sign-up-on-trieve]\n\n<FeedbackBlock\n  id=\"76bd080ccf0cc7dc\"\n  body=\"Sign up and create a dataset. Then obtain 2 API keys where one has only read access and the other has admin access to create and delete chunks.\nStore these credentials in environment variables.\"\n>\n  Sign up and create a dataset. Then obtain 2 API keys where one has only read access and the other has admin access to create and delete chunks.\n  Store these credentials in environment variables.\n</FeedbackBlock>\n\n<Callout title=\"Notice\">\n  One API Key should have only read access for the public facing search and the other should have\n  admin access to create and delete chunks.\n</Callout>\n\nSync Dataset [#sync-dataset]\n\n<FeedbackBlock id=\"d9ead6dcff216233\" body=\"Export the search indexes by pre-rendering a static route.\">\n  Export the search indexes by pre-rendering a static route.\n</FeedbackBlock>\n\n```ts title=\"lib/export-search-indexes.ts\"\nimport { source } from '@/lib/source';\nimport { type TrieveDocument } from 'trieve-fumadocs-adapter/search/sync';\n\nexport async function exportSearchIndexes() {\n  const results: TrieveDocument[] = [];\n\n  for (const page of source.getPages()) {\n    results.push({\n      _id: page.url,\n      structured: page.data.structuredData,\n      url: page.url,\n      title: page.data.title,\n      description: page.data.description,\n    });\n  }\n\n  return results;\n}\n```\n\n<CodeBlockTabs defaultValue=\"Next.js\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"Next.js\">\n      Next.js\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"React Router\">\n      React Router\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"Tanstack Start\">\n      Tanstack Start\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"Waku\">\n      Waku\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"Next.js\">\n    ```ts  title=\"app/static.json/route.ts\"\n    import { exportSearchIndexes } from '@/lib/export-search-indexes';\n\n    export const revalidate = false;\n\n    export async function GET() {\n      return Response.json(await exportSearchIndexes());\n    }\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"React Router\">\n    ```ts  title=\"app/routes/static.ts\"\n    import { exportSearchIndexes } from '@/lib/export-search-indexes';\n\n    export async function loader() {\n      return Response.json(await exportSearchIndexes());\n    }\n    ```\n\n    ```ts  title=\"app/routes.ts\"\n    import { route, type RouteConfig } from '@react-router/dev/routes';\n\n    export default [\n      // [!code ++]\n      route('static.json', 'routes/static.ts'),\n    ] satisfies RouteConfig;\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"Tanstack Start\">\n    ```ts  title=\"src/routes/static[.]json.ts\"\n    import { createFileRoute } from '@tanstack/react-router';\n    import { exportSearchIndexes } from '@/lib/export-search-indexes';\n\n    export const Route = createFileRoute('/static.json')({\n      server: {\n        handlers: {\n          GET: async () => Response.json(await exportSearchIndexes()),\n        },\n      },\n    });\n    ```\n\n    ```ts  title=\"vite.config.ts\"\n    import { tanstackStart } from '@tanstack/react-start/plugin/vite';\n    import { defineConfig } from 'vite';\n\n    export default defineConfig({\n      plugins: [\n        // ...\n        tanstackStart({\n          prerender: {\n            enabled: true,\n          },\n          // [!code ++] pre-render the static file\n          pages: [{ path: '/static.json' }],\n        }),\n      ],\n    });\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"Waku\">\n    ```ts  title=\"pages/api/static.json.ts\"\n    import { exportSearchIndexes } from '@/lib/export-search-indexes';\n\n    export async function GET() {\n      return Response.json(await exportSearchIndexes());\n    }\n\n    export const getConfig = () => ({\n      render: 'static',\n    });\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\n<FeedbackBlock id=\"25e82413e445f7e0\" body=\"Create a script, the sync function will sync search indexes.\">\n  Create a script, the `sync` function will sync search indexes.\n</FeedbackBlock>\n\n```ts title=\"scripts/sync-content.ts\"\nimport * as fs from 'node:fs';\nimport { sync, type TrieveDocument } from 'trieve-fumadocs-adapter/search/sync';\nimport { TrieveSDK } from 'trieve-ts-sdk';\n\n// the path of pre-rendered `static.json`, choose one according to your React framework\nconst filePath = {\n  next: '.next/server/app/static.json.body',\n  'tanstack-start': '.output/public/static.json',\n  'react-router': 'build/client/static.json',\n  waku: 'dist/public/static.json',\n}['next'];\n\nconst content = fs.readFileSync(filePath);\n\nconst records: TrieveDocument[] = JSON.parse(content.toString());\n\nconst client = new TrieveSDK({\n  apiKey: 'adminApiKey',\n  datasetId: 'datasetId',\n});\n\nsync(client, records);\n```\n\n<FeedbackBlock id=\"c862bc499d3e496e\" body=\"Make sure to run the script after build:\">\n  Make sure to run the script after build:\n</FeedbackBlock>\n\n```json title=\"package.json\"\n{\n  \"scripts\": {\n    \"build\": \"... && bun scripts/sync-content.ts\"\n  }\n}\n```\n\n> <FeedbackBlock id=\"da9013874471a1b6\" body=\"You can also integrate it with your CI/CD pipeline.\">\n>   You can also integrate it with your CI/CD pipeline.\n> </FeedbackBlock>\n\nSearch UI [#search-ui]\n\n<FeedbackBlock id=\"4fa97735a2720c7e\" body=\"You can use their SearchDialog component:\">\n  You can use their `SearchDialog` component:\n</FeedbackBlock>\n\n```tsx title=\"components/search.tsx\"\n'use client';\nimport type { SharedProps } from 'fumadocs-ui/components/dialog/search';\nimport SearchDialog from 'trieve-fumadocs-adapter/components/dialog/search';\nimport { TrieveSDK } from 'trieve-ts-sdk';\n\nconst trieveClient = new TrieveSDK({\n  apiKey: 'readOnlyApiKey',\n  datasetId: 'datasetId',\n});\n\nexport default function CustomSearchDialog(props: SharedProps) {\n  return <SearchDialog trieveClient={trieveClient} {...props} />;\n}\n```\n\n<FeedbackBlock id=\"d6e2ae96bccf525a\" body=\"Replace apiKey and datasetId with your desired values.Replace the default search dialog with your new one.\">\n  1. Replace `apiKey` and `datasetId` with your desired values.\n\n  2. Replace the default search dialog with your new one.\n</FeedbackBlock>\n\nSearch Client [#search-client]\n\n<FeedbackBlock id=\"ebdafb6a81be3832\" body=\"Add the useTrieveSearch hook:\">\n  Add the `useTrieveSearch` hook:\n</FeedbackBlock>\n\n```ts\nimport { TrieveSDK } from 'trieve-ts-sdk';\nimport { useTrieveSearch } from 'trieve-fumadocs-adapter/search/trieve';\n\nconst client = new TrieveSDK({\n  apiKey: 'readOnlyApiKey',\n  datasetId: 'datasetId',\n});\n\nconst { search, setSearch, query } = useTrieveSearch(client);\n```\n\nOptions [#options]\n\nTag Filter [#tag-filter]\n\n<FeedbackBlock id=\"8473e550c5a1a0d5\" body=\"To configure tag filtering, add a tag value to indexes.\">\n  To configure tag filtering, add a `tag` value to indexes.\n</FeedbackBlock>\n\n```js\nimport { sync } from 'trieve-fumadocs-adapter/search/sync';\nimport { TrieveSDK } from 'trieve-ts-sdk';\n\nconst client = new TrieveSDK({\n  apiKey: 'adminApiKey',\n  datasetId: 'datasetId',\n});\n\nconst documents = records.map((index) => ({\n  ...index,\n  tag: 'value', // [!code highlight]\n}));\n\nsync(client, documents);\n```\n\nSearch UI [#search-ui-1]\n\n<FeedbackBlock id=\"8f30fe740976c12c\" body=\"Enable Tag Filter.\">\n  Enable Tag Filter.\n</FeedbackBlock>\n\n```tsx title=\"components/search.tsx\"\nimport SearchDialog from 'trieve-fumadocs-adapter/components/dialog/search';\n\n<SearchDialog\n  defaultTag=\"value\"\n  tags={[\n    {\n      name: 'Tag Name',\n      value: 'value',\n    },\n  ]}\n/>;\n```\n\nSearch Client [#search-client-1]\n\n<FeedbackBlock id=\"a9990c15a1cb1ec4\" body=\"The tag_set field is an attribute for filtering. To filter indexes by tag, use the filter on Trieve search clients.\">\n  The `tag_set` field is an attribute for filtering. To filter indexes by tag, use the filter on Trieve search clients.\n</FeedbackBlock>\n\n```json\n{\n  \"must\": [\n    {\n      \"field\": \"tag_set\",\n      \"match\": [\"value\"]\n    }\n  ]\n}\n```\n\n<FeedbackBlock id=\"6c1fe9c6fde73579\" body=\"Or with useTrieveSearch hook:\">\n  Or with `useTrieveSearch` hook:\n</FeedbackBlock>\n\n```ts\nimport { TrieveSDK } from 'trieve-ts-sdk';\nimport { useTrieveSearch } from 'trieve-fumadocs-adapter/search/trieve';\n\nconst client = new TrieveSDK({\n  apiKey: 'readOnlyApiKey',\n  datasetId: 'datasetId',\n});\n\nconst { search, setSearch, query } = useTrieveSearch(client, undefined, '<your tag value>');\n```\n";
